    return null;
}

// 1. Haal de datapunten eruit inclusief de exacte tijd in milliseconden
let parsedRecords = [];
records.forEach(item => {
    let p = parseFloat(item.imbalanceprice);
    if (!isNaN(p) && item.datetime) {
        parsedRecords.push({
            timeMs: new Date(item.datetime).getTime(),
            p: p
        });
    }
});

// Zorg dat ze altijd netjes chronologisch staan
parsedRecords.sort((a, b) => a.timeMs - b.timeMs);

// 2. Bouw het payload-lijstje voor InfluxDB
let points = [];
parsedRecords.forEach(pr => {
    points.push({
        measurement: "onbalans_minuut",
        fields: { prijs: pr.p },
        tags: { type: "onbalans" },
        timestamp: new Date(pr.timeMs)
    });
});

// 3. Spoor de ontbrekende gaten op als we onder de 1440 minuten duiken
let ontbrekendeMinuten = [];
if (points.length < 1440) {
    // Exacte start en eind van deze dag (in UTC)
    let startOfDayMs = new Date(msg.dag + "T00:00:00Z").getTime();
    let endOfDayMs = startOfDayMs + (24 * 60 * 60 * 1000); 

    // We maken een check-lijst inclusief virtuele meetpunten aan de rand van de dag,
    // zodat hij ook gaten ontdekt als Elia de allereerste of allerlaatste minuut vergeet.
    let checkRecords = [
        { timeMs: startOfDayMs - 60000 }, 
        ...parsedRecords,
        { timeMs: endOfDayMs }            
    ];

    let formatT = (ms) => {
        let d = new Date(ms);
        // Lokale tijd voor in je Node-RED debug paneel
        return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
    };

    for (let i = 1; i < checkRecords.length; i++) {
        let diff = checkRecords[i].timeMs - checkRecords[i-1].timeMs;

        // Is het gat groter dan 1 minuut (60.000 ms)? Dan missen we data!
        if (diff > 60000) { 
            let gatStartMs = checkRecords[i-1].timeMs + 60000;
            let gatEindMs = checkRecords[i].timeMs - 60000;

            if (gatStartMs === gatEindMs) {
                ontbrekendeMinuten.push(formatT(gatStartMs)); // Eén losse minuut mist
            } else {
                ontbrekendeMinuten.push(`${formatT(gatStartMs)}-${formatT(gatEindMs)}`); // Heel blok mist
            }
        }
    }

    // 4. Stuur de gaten netjes naar je Debug paneel
    let tekort = 1440 - points.length;
    node.status({ fill: "yellow", shape: "dot", text: `${points.length} min (mist ${tekort})` });

    if (points.length === 1380) {
        node.warn(`ℹ️ ${msg.dag} mist 60 min: ${ontbrekendeMinuten.join(', ')} (Waarschijnlijk Zomertijd)`);
    } else {
        node.warn(`⚠️ ELIA: ${msg.dag} mist ${tekort} min! Gaten: [${ontbrekendeMinuten.join(' | ')}]`);
    }
} else if (points.length > 1440) {
    node.status({ fill: "blue", shape: "dot", text: `${points.length} min` });
} else {
    node.status({ fill: "green", shape: "dot", text: `${msg.dag}: 1440 min` });
}

msg.payload = points;
return msg;

